type ProjectArchiveCardProps = {
    locale: SiteLocale;
    project: Project;
    index: number;
};

function ProjectArchiveCard({ locale,
                                project,
                                index,
                            }: ProjectArchiveCardProps) {
    const t = translator(locale);
    const colors =
        project.caseStudy.visualSystem.colors;

    const primary =
        colors[0]?.value ?? "#5E56E7";

    const secondary =
        colors[1]?.value ?? "#1E1E1E";

    const accent =
        colors[2]?.value ?? "#F1F1F3";

    const typeLabel =
        localized(projectTypeLabels[
            project.type
            ], locale);

    const statusLabel =
        localized(projectStatusLabels[
            project.status
            ], locale);

    return (
        <article
            className="group relative w-full border border-[#A2A3AA] bg-[#FEFEFE] transition-[border-color,box-shadow,transform] duration-300 ease-out hover:-translate-y-1 hover:border-[#5E56E7] hover:shadow-[0_18px_50px_rgb(30_30_30/0.08)] focus-within:border-[#5E56E7]"
            data-archive-card=""
            data-archive-card-index={index}
        >
            <Link
                id={`project-modal-trigger-${project.slug}`}
                href={publicPath(locale, `/projects/${project.slug}`)}
                scroll={false}
                aria-haspopup="dialog"
                aria-label={t("Open {title} case study", { title: project.title })}
                className="block h-full text-inherit no-underline focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[#5E56E7]"
            >
                <div
                    className="relative aspect-[1.4/1] overflow-hidden sm:aspect-[640/318]"
                    data-archive-card-visual=""
                >
                    {project.coverImage ? (
                        <Image
                            src={
                                project
                                    .coverImage
                                    .src
                            }
                            alt={
                                localized(project
                                    .coverImage
                                    .alt, locale)
                            }
                            width={
                                project
                                    .coverImage
                                    .width
                            }
                            height={
                                project
                                    .coverImage
                                    .height
                            }
                            className="h-full w-full object-cover transition duration-500 group-hover:scale-[1.015]"
                        />
                    ) : (
                        <ProjectVisualFallback locale={locale}
                                               project={project}
                                               primary={primary}
                                               secondary={secondary}
                                               accent={accent}
                        />
                    )}

                    <div className="absolute inset-x-0 bottom-0 flex items-center justify-between border-t border-white/20 bg-black/15 px-4 py-3 backdrop-blur-[2px]">
                        <span className="text-[10px] font-bold uppercase tracking-[0.12em] text-white/70">
                            {
                                project
                                    .caseStudy
                                    .identifier
                            }
                        </span>

                        <span className="text-[10px] font-bold uppercase tracking-[0.12em] text-white">
                            {t("Explore case →")}
                            </span>
                    </div>
                </div>

                <div
                    className="flex flex-col items-start gap-[15px] p-[clamp(16px,2vw,22px)]"
                    data-archive-card-copy=""
                >
                    <div className="flex flex-wrap items-center gap-2">
                        <span className="bg-[#1E1E1E] px-2.5 py-1.5 text-[10px] font-bold uppercase leading-none tracking-[0.06em] text-[#BFC0C3]">
                            {typeLabel}
                        </span>

                        <span className="border border-[#D7D7DA] px-2.5 py-1.5 text-[10px] font-bold uppercase leading-none tracking-[0.06em] text-[#8A8B90]">
                            {project.year}
                        </span>
                    </div>

                    <h3 className="text-[clamp(22px,2.4vw,30px)] font-black uppercase leading-[0.95] tracking-[-0.02em] text-[#303031]">
                        {project.title}
                    </h3>

                    <p className="max-w-[560px] text-xs font-bold leading-[1.4] text-[#A8A9AD]">
                        {
                            localized(project
                                .summary, locale)
                        }
                    </p>

                    <div className="grid w-full grid-cols-2 gap-4 border-t border-[#DDDDDD] pt-[18px] sm:grid-cols-3">
                        <ProjectStat locale={locale}
                                     label={t("Status")}
                                     value={statusLabel}
                                     status
                        />

                        <ProjectStat locale={locale}
                                     label={t("System")}
                                     value={
                                         localized(project
                                             .caseStudy
                                             .presentation
                                             .centerLabel, locale)
                                     }
                        />

                        <ProjectStat locale={locale}
                                     label={t("Stack")}
                                     value={`${project.technologies.length} technologies`}
                        />
                    </div>
                </div>
            </Link>
        </article>
    );
}

type ProjectVisualFallbackProps = {
    locale: SiteLocale;
    project: Project;
    primary: string;
    secondary: string;
    accent: string;
};

function ProjectVisualFallback({ locale,
                                   project,
                                   primary,
                                   secondary,
                                   accent,
                               }: ProjectVisualFallbackProps) {
    const t = translator(locale);
    return (
        <div
            className="relative h-full w-full overflow-hidden bg-[#151619]"
            aria-hidden="true"
            data-project-visual={project.slug}
        >
            <div
                className="absolute inset-0 opacity-30"
                style={{
                    background: `radial-gradient(circle at 12% 8%, ${primary} 0%, transparent 34%), radial-gradient(circle at 92% 88%, ${secondary} 0%, transparent 30%)`,
                }}
            />

            <div className="absolute inset-[clamp(14px,3vw,28px)] flex flex-col overflow-hidden border border-white/25 bg-[#17181B]/90">
                <div className="flex items-center justify-between border-b border-white/15 px-4 py-3 sm:px-5">
                    <span className="text-[9px] font-bold uppercase tracking-[0.16em] text-white/55">
                        {
                            project
                                .caseStudy
                                .identifier
                        }
                    </span>

                    <span className="text-[9px] font-bold uppercase tracking-[0.16em] text-white/75">
                        {t("System view")}
                        </span>
                </div>

                <div className="relative min-h-0 flex-1">
                    {project.slug ===
                    "pixardia-digital-studio" ? (
                        <PixardiaProjectVisual locale={locale}
                                               primary={primary}
                                               accent={accent}
                        />
                    ) : project.slug ===
                    "nexus-finance" ? (
                        <NexusProjectVisual locale={locale}
                                            primary={primary}
                                            accent={accent}
                        />
                    ) : project.slug ===
                    "nordmarkt-commerce" ? (
                        <NordmarktProjectVisual locale={locale}
                                                primary={primary}
                                                accent={accent}
                        />
                    ) : (
                        <CoreFlowProjectVisual locale={locale}
                                               primary={primary}
                                               accent={accent}
                        />
                    )}
                </div>
            </div>
        </div>
    );
}

